CREATE TABLE "plugin_wattanam_academic_management_study_year" ("id" TEXT PRIMARY KEY, "year" INTEGER NOT NULL, "label" TEXT, "startDate" TIMESTAMPTZ, "endDate" TIMESTAMPTZ, "isCurrent" BOOLEAN NOT NULL DEFAULT FALSE, "schoolName" TEXT, "logoUrl" TEXT, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "currentMarker" SMALLINT GENERATED ALWAYS AS (CASE WHEN "isCurrent" THEN 1 ELSE NULL END) STORED, CONSTRAINT "academic_study_year_unique_year" UNIQUE ("year"), CONSTRAINT "academic_study_year_one_current" UNIQUE ("currentMarker"));
